// Author: DevOps Team
// Version: 1.2

import { SuperpowerSkill } from '@superpowers/core';

export const jiraBulkUpdater: SuperpowerSkill = {
  id: 'jira-bulk-updater',
  name: 'Jira Bulk Issue Updater',
  description: 'Updates multiple Jira issues based on custom filters and field changes',
  parameters: {
    jiraUrl: {
      type: 'string',
      description: 'URL cơ sở của instance Jira của bạn (ví dụ: https://yourcompany.atlassian.net)',
      required: true
    },
    apiToken: {
      type: 'string',
      description: 'Jira API token (tạo tại https://id.atlassian.com/manage-profile/security/api-tokens)',
      required: true,
      secret: true
    },
    projectKey: {
      type: 'string',
      description: 'Bộ lọc key dự án JQL (ví dụ: PROJ)',
      required: true
    },
    statusUpdate: {
      type: 'string',
      description: 'Trạng thái mới cần áp dụng (ví dụ: "In Progress" hoặc "Resolved")',
      required: true
    },
    priorityUpdate: {
      type: 'string',
      description: 'Cập nhật độ ưu tiên tùy chọn (ví dụ: "High")',
      required: false
    },
    comment: {
      type: 'string',
      description: 'Bình luận tùy chọn để thêm vào mỗi issue',
      required: false
    }
  },
  execute: async ({ jiraUrl, apiToken, projectKey, statusUpdate, priorityUpdate, comment }) => {
    try {
      const jira = new JiraClient(jiraUrl, apiToken);
      const issues = await jira.searchIssues(`project = ${projectKey}`);

      if (issues.length === 0) {
        return {
          success: true,
          message: `Không tìm thấy issue nào cho dự án ${projectKey}`,
          updatedCount: 0
        };
      }

      let updatedCount = 0;
      const errors: string[] = [];

      for (const issue of issues) {
        try {
          await jira.updateIssue(issue.key, {
            status: statusUpdate,
            priority: priorityUpdate,
            comment: comment
          });
          updatedCount++;
        } catch (error) {
          errors.push(`Không thể cập nhật ${issue.key}: ${error.message}`);
        }
      }

      return {
        success: errors.length === 0,
        message: errors.length > 0 
          ? `${updatedCount} issue đã được cập nhật với ${errors.length} lỗi`
          : `Đã cập nhật thành công ${updatedCount} issue`,
        updatedCount,
        errors
      };
    } catch (error) {
      throw new Error(`Cập nhật hàng loạt trên Jira thất bại: ${error.message}`);
    }
  }
};
```

